import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import io.github.resilience4j.retry.annotation.Retry;
import org.springframework.stereotype.Service;

@Service
public class OrderService {
    @Retry(name = "paymentRetry", fallbackMethod = "paymentFallback")
    @CircuitBreaker(name = "paymentCB", fallbackMethod = "paymentFallback")
    public String processPayment(String orderId) {
        // Call external payment gateway API
        return restTemplate.getForObject("http://payment-service/pay", String.class);
    }

    public String paymentFallback(String orderId, Throwable t) {
        return "Payment Pending - Fallback Processed";
    }
}

